def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    my_c = sum(1 for a, b in history if a == 'C')
    opp_c = sum(1 for a, b in history if b == 'C')
    my_rate = my_c / n if n > 0 else 1.0

    # Detect persistent defection and defect
    if n >= 2 and (n - opp_c) >= n * 0.8:
        return 'D'

    # Endgame: last 5 rounds, defect if opponent likely cooperates or we are behind
    if n >= 95:
        if opp_c >= n * 0.7:
            return 'D'
        if opp_c < n * 0.3:
            return 'D'
        my_score = 0
        opp_score = 0
        for a, b in history:
            if a == 'C' and b == 'C':
                my_score += 3
                opp_score += 3
            elif a == 'D' and b == 'C':
                my_score += 5
            elif a == 'C' and b == 'D':
                opp_score += 5
            else:
                my_score += 1
                opp_score += 1
        if my_score < opp_score:
            return 'D'
        return 'C'

    # If opponent defected last round
    if opp_last == 'D':
        # If we are being exploited (high cooperation rate), punish
        if my_rate > 0.8:
            return 'D'
        # If we defected last round, forgive to break cycle
        if my_last == 'D':
            return 'C'
        # Otherwise retaliate once
        return 'D'

    # Opponent cooperated last round
    # If we defected last round, cooperate to restore
    if my_last == 'D':
        return 'C'

    # Periodic probing: defect every 6th round (when n % 6 == 5)
    if n % 6 == 5:
        return 'D'

    return 'C'
